import math

def sum(a, b):
    """Return the sum of all common divisors of a and b."""
    total = 0
    n = math.gcd(a, b)
    limit = int(math.isqrt(n)) + 1
    for i in range(1, limit):
        if n % i == 0:
            total += i
            other = n // i
            if other != i:
                total += other
    return total
